function persistableRoom(room){ const copy={...room}; delete copy.code; delete copy.players; delete copy.mediaSources; return copy; }
function mediaTrackMeta(track){ if(!track||typeof track!=='object')return track; const {url,_assetId,_mime,...meta}=track; return meta; }
