function sceneSnapshot(room){return {currentImage:room.currentImage||null,gridConfig:normalizeGridConfig(room.gridConfig),tokens:Array.isArray(room.tokens)?room.tokens:[],sceneState:normalizeSceneState(room.sceneState),sharedMusic:(room.sharedMusic||[]).map(mediaTrackMeta),musicState:musicPayload(room),sharedSfx:(room.sharedSfx||[]).map(mediaTrackMeta),sfxState:room.sfxState||{trackId:null,playing:false,loop:false,startedAt:null}};}
function approvalPage(title,body,ok=true){ const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch])); return `<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)}</title><body style="margin:0;background:#0a0a12;color:#eee;font-family:Arial,sans-serif;display:grid;place-items:center;min-height:100vh"><main style="max-width:560px;padding:28px;background:#151521;border-radius:16px;border:1px solid #333"><h1 style="color:${ok?'#00d9a5':'#ff5577'}">${esc(title)}</h1><p style="line-height:1.6">${esc(body)}</p></main></body></html>`; }

