  async rtkApi(suffix,options={}){const account=encodeURIComponent(String(this.env.CLOUDFLARE_ACCOUNT_ID||'').trim()),app=encodeURIComponent(String(this.env.CLOUDFLARE_REALTIMEKIT_APP_ID||'').trim());const res=await fetch(`${RTK_API_ROOT}/accounts/${account}/realtime/kit/${app}${suffix}`,{method:options.method||'GET',headers:{Authorization:`Bearer ${String(this.env.CLOUDFLARE_REALTIMEKIT_API_TOKEN||'').trim()}`,'Content-Type':'application/json'},body:options.body===undefined?undefined:JSON.stringify(options.body)});let p=null;try{p=await res.json();}catch(_){}if(!res.ok||p?.success===false)throw new Error(p?.errors?.[0]?.message||`RealtimeKit HTTP ${res.status}`);return p?.data??p;}
