  async webSocketMessage(ws,message){try{const msg=JSON.parse(typeof message==='string'?message:new TextDecoder().decode(message));if(msg&&typeof msg.event==='string')await this.handleEvent(ws,msg.event,msg.data);}catch(err){console.error('ws message',err);}}
