function withSecurityHeaders(response){const h=new Headers(response.headers);h.set('Permissions-Policy','camera=(self), microphone=(self)');h.set('X-Content-Type-Options','nosniff');return new Response(response.body,{status:response.status,statusText:response.statusText,headers:h});}
async function stubForCode(env,code){return env.RPG_CONTAINER.get(env.RPG_CONTAINER.idFromName(cleanCode(code)));}

function retargetRequest(request, url) {
  const method = request.method || 'GET';
  const init = { method, headers: request.headers, redirect: request.redirect };
  if (method !== 'GET' && method !== 'HEAD') init.body = request.body;
  return new Request(url, init);
}

export default {
  async fetch(request,env){
    const url=new URL(request.url);
    if(url.pathname==='/health')return Response.json({ok:true,storage:'durable-object-sqlite-free',plan:'Workers Free compatible',videoProvider:String(env.CLOUDFLARE_REALTIMEKIT_API_TOKEN||'')?'cloudflare-realtimekit':'webrtc-p2p-fallback',realtimeKitConfigured:Boolean(env.CLOUDFLARE_ACCOUNT_ID&&env.CLOUDFLARE_REALTIMEKIT_APP_ID&&env.CLOUDFLARE_REALTIMEKIT_API_TOKEN)});
    if(url.pathname==='/ws'){
      const campaign=cleanLabel(url.searchParams.get('campaign'),100),system=validSystem(url.searchParams.get('system'));if(!campaign||!system)return new Response('campaign/system ausente',{status:400});const code=await internalCodeForCampaign(keyForLabel(campaign),system);url.searchParams.set('code',code);const stub=await stubForCode(env,code);return stub.fetch(retargetRequest(request,url.toString()));
    }
    let code='';
    if(url.pathname.startsWith('/api/room-image/')||url.pathname.startsWith('/api/asset/')){const parts=url.pathname.split('/').filter(Boolean);code=decodeURIComponent(parts[2]||'');}
    else if(url.pathname==='/api/room-image/upload')code=request.headers.get('x-room-code')||'';
    else if(url.pathname==='/api/room-image/from-url'||url.pathname==='/api/v6-resend-approval'){const b=await request.clone().json().catch(()=>({}));code=String(b.room||'');}
    else if(url.pathname==='/api/v6-approval-status'||url.pathname==='/v6/approve'||url.pathname==='/v6/reject')code=url.searchParams.get('room')||'';
    if(code){url.searchParams.set('code',cleanCode(code));const stub=await stubForCode(env,code);return stub.fetch(retargetRequest(request,url.toString()));}
    const asset=await env.ASSETS.fetch(request);return withSecurityHeaders(asset);
  }
};
